files['com/oplus/settings/feature/display/ScreenRefreshRateFragment.java']='''package com.oplus.settings.feature.display;public class ScreenRefreshRateFragment {public Screen screen=new Screen();public void onResume(){}public void refreshRateSettingSummary(int a,int b){}public Screen getPreferenceScreen(){return screen;}public android.content.Context getContext(){return new android.content.Context();}public static class Screen {public RefreshRateMenuPreference pref=new RefreshRateMenuPreference();public androidx.preference.Preference category=new androidx.preference.Preference();public Object findPreference(String key){return key.equals("refresh_rate_setting")?pref:key.equals("screen_refresh_rate_settings")?category:null;}public void removePreference(Object p){throw new AssertionError("Unexpected row removal");}}}'''
files['com/refresh165/SettingsTest.java']='''package com.refresh165;import android.os.Bundle;public class SettingsTest {static int checks;static void yes(boolean b){checks++;if(!b)throw new AssertionError("settings "+checks);}public static void main(String[]a)throws Exception{Bundle b=new Bundle();b.putInt("rate",144);java.lang.reflect.Field f=Config.class.getDeclaredField("values");f.setAccessible(true);f.set(null,b);SettingsIntegration.install(SettingsTest.class.getClassLoader());com.oplus.settings.feature.display.ScreenRefreshRateFragment fragment=new com.oplus.settings.feature.display.ScreenRefreshRateFragment();Object original=fragment.screen.pref;com.refresh165.xp.XposedBridge.run(fragment,"onResume");yes(fragment.screen.pref==original);yes(fragment.screen.pref.entries.length==5);yes(fragment.screen.pref.entries[3].equals("144 Hz"));yes(fragment.screen.pref.value.equals("144"));yes(fragment.screen.pref.menu);yes(fragment.screen.category.visible);yes(!fragment.screen.pref.persistent);yes(fragment.screen.pref.listener!=null);b.putBoolean("menu",false);com.refresh165.xp.XposedBridge.run(fragment,"onResume");yes(fragment.screen.pref.entries.length==2);yes(fragment.screen.pref.value.equals("3"));yes(fragment.screen.pref.persistent);yes(!fragment.screen.category.visible);yes(fragment.screen.pref.listener==null);System.out.println("PASS "+checks+" original OEM menu / restore assertions");}}'''
